/**
 * Name normalisation for the ЄДР history (port of forensic app/registers/norm.py:
 * norm_ua, _skeleton, ua_match_key). Golden tests in __tests__/norm.test.ts were
 * generated by running the Python original on the same inputs; keep the two in step.
 *
 * normUa      'ТОВ "АЛЬФА-ВЕСТ"' -> 'тов альфа вест': Latin accents dropped, Cyrillic kept
 *             (й, ї, ё are not decomposed), apostrophes and quotes dropped inside words.
 * uaMatchKey  Latin skeleton of every word, without legal-form words and initials. The same
 *             for a Cyrillic register entry and a Latin query:
 *             'СКАРАМАНДЕР ЛІМІТЕД' and 'Scaramander Limited' -> 'skaramander'.
 */

const UA_KEEP = new Set(['й', 'ї', 'ё', 'Й', 'Ї', 'Ё']);
const UA_DROP = new Set(["'", '’', 'ʼ', '`', '´', '‘', '"', '«', '»', '“', '”', '„']);
const UA_NON = /[^0-9a-zа-яіїєґё]+/g;
const COMBINING = /\p{Mn}/u;

const UA_LAT: Record<string, string> = {
  а: 'a', б: 'b', в: 'v', г: 'h', ґ: 'g', д: 'd', е: 'e', є: 'ie', ж: 'zh', з: 'z',
  и: 'y', і: 'i', ї: 'i', й: 'i', к: 'k', л: 'l', м: 'm', н: 'n', о: 'o', п: 'p',
  р: 'r', с: 's', т: 't', у: 'u', ф: 'f', х: 'kh', ц: 'ts', ч: 'ch', ш: 'sh',
  щ: 'shch', ь: '', ю: 'iu', я: 'ia', ё: 'e', ы: 'y', э: 'e', ъ: '',
};

// Latin spelling differences between a name in its own language and its Ukrainian
// transcription, reduced to one skeleton on both sides (order matters).
const SKEL: Array<[string, string]> = [
  ['sch', 'sh'], ['ch', 'k'], ['ph', 'f'], ['th', 't'], ['ck', 'k'], ['kh', 'h'], ['x', 'ks'],
  ['q', 'k'], ['w', 'v'], ['c', 'k'], ['g', 'h'], ['j', 'dzh'], ['y', 'i'],
];

const UA_LEGAL_WORDS = `товариство обмеженою відповідальністю приватне підприємство акціонерне публічне закрите
    відкрите дочірнє компанія корпорація фірма тов тзов пп ат пат прат зат ват дп лімітед лтд ллс ллк гмбх інк
    корп limited ltd llc lls inc gmbh corp company co plc sa sarl srl spa bv nv ag oy ab as kg sp zoo`
  .split(/\s+/).filter(Boolean);

export function normUa(s: string | null | undefined): string {
  if (!s) return '';
  let out = '';
  for (const ch of s) {
    if (UA_DROP.has(ch)) continue;
    if (UA_KEEP.has(ch)) { out += ch; continue; }
    for (const c of ch.normalize('NFKD')) {
      if (!COMBINING.test(c)) out += c;
    }
  }
  return out.toLowerCase().replace(/ё/g, 'е').replace(UA_NON, ' ').trim();
}

export function skeleton(word: string): string {
  let w = '';
  for (const ch of word) w += UA_LAT[ch] ?? ch;
  for (const [a, b] of SKEL) w = w.split(a).join(b);
  w = w.replace(/([aeiou])h(?![aeiou])/g, '$1'); // silent h: John / ДЖОН
  return w.replace(/(.)\1+/g, '$1');               // doubled letters: ФФ / ff
}

const UA_LEGAL = new Set(UA_LEGAL_WORDS.map(skeleton));

export function uaMatchKey(s: string | null | undefined): string {
  const words = normUa(s).split(' ').filter(Boolean).map(skeleton);
  const seen = new Set<string>();
  const out: string[] = [];
  for (const w of words) {
    if (w.length > 1 && !UA_LEGAL.has(w) && !seen.has(w)) {
      seen.add(w);
      out.push(w);
    }
  }
  return out.join(' ');
}

/**
 * History key of a person or company name: the match key without a parenthesised
 * alias, so 'СКАРАМАНДЕР ЛІМІТЕД (SCARAMANDER LIMITED)' in an old dump and
 * 'СКАРАМАНДЕР ЛІМІТЕД' now are one value.
 */
export function historyNameKey(name: string | null | undefined): string {
  return uaMatchKey((name || '').replace(/\([^)]*\)/g, ' ')) || uaMatchKey(name);
}

