/** 'Кіпр' -> 'CY'; a two-letter Latin code is passed through; unknown names -> null. */
export function countryIso(s: string | null | undefined): string | null {
  const t = (s || '').trim();
  if (/^[A-Za-z]{2}$/.test(t)) return t.toUpperCase();
  const n = normUa(t);
  if (!n) return null;
  return COUNTRY[n] || COUNTRY[n.replace(/^республіка /, '')] || null;
}
